namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

public class Instructor
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Bio { get; set; } = string.Empty;
    public string Email { get; set; } = string.Empty;
}

public class Course
{
    public int Id { get; set; }
    public string Code { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public int DepartmentId { get; set; }
    public Department Department { get; set; } = null!;
    public Instructor Instructor { get; set; } = null!;
    public bool IsFeatured { get; set; }
}

public class EnrollmentRequest
{
    public string StudentName { get; set; } = string.Empty;
    public string StudentId { get; set; } = string.Empty;
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;
    private readonly List<EnrollmentRequest> _enrollments = new();

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 4, Name = "English", Code = "ENG", Description = "Study of literature, writing, and language." },
            new() { Id = 5, Name = "History", Code = "HIST", Description = "Study of past events and civilizations." }
        };

        _instructors = new List<Instructor>
        {
            new() { Id = 1, Name = "Dr. Sarah Chen", Title = "Professor", Bio = "Specializes in distributed systems and cloud computing with 15 years of teaching experience.", Email = "s.chen@university.edu" },
            new() { Id = 2, Name = "Dr. James Morrison", Title = "Associate Professor", Bio = "Research focus on algebraic topology and its applications in data science.", Email = "j.morrison@university.edu" },
            new() { Id = 3, Name = "Dr. Elena Rodriguez", Title = "Professor", Bio = "Award-winning physicist specializing in quantum mechanics and particle physics.", Email = "e.rodriguez@university.edu" },
            new() { Id = 4, Name = "Dr. Michael Park", Title = "Assistant Professor", Bio = "Published author focusing on modern American literature and creative writing.", Email = "m.park@university.edu" },
            new() { Id = 5, Name = "Dr. Aisha Williams", Title = "Professor", Bio = "Expert in medieval European history with extensive fieldwork in archaeological sites.", Email = "a.williams@university.edu" },
            new() { Id = 6, Name = "Dr. Robert Liu", Title = "Associate Professor", Bio = "Focuses on machine learning, neural networks, and artificial intelligence ethics.", Email = "r.liu@university.edu" }
        };

        _courses = new List<Course>
        {
            new() { Id = 1, Code = "CS 101", Title = "Introduction to Programming", Description = "Fundamental concepts of programming using Python. Covers variables, control structures, functions, and basic data structures.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", DepartmentId = 1, Instructor = _instructors[0], Department = _departments[0], IsFeatured = true },
            new() { Id = 2, Code = "CS 301", Title = "Data Structures & Algorithms", Description = "Advanced data structures including trees, graphs, and hash tables. Algorithm design and complexity analysis.", Credits = 4, Schedule = "Tue/Thu 10:30 AM–12:00 PM", DepartmentId = 1, Instructor = _instructors[0], Department = _departments[0], IsFeatured = true },
            new() { Id = 3, Code = "CS 450", Title = "Machine Learning", Description = "Introduction to machine learning techniques including supervised and unsupervised learning, neural networks, and model evaluation.", Credits = 3, Schedule = "Mon/Wed 2:00–3:30 PM", DepartmentId = 1, Instructor = _instructors[5], Department = _departments[0], IsFeatured = true },
            new() { Id = 4, Code = "MATH 201", Title = "Linear Algebra", Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues and eigenvectors.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", DepartmentId = 2, Instructor = _instructors[1], Department = _departments[1] },
            new() { Id = 5, Code = "MATH 301", Title = "Abstract Algebra", Description = "Groups, rings, fields, and their applications in modern mathematics and computer science.", Credits = 3, Schedule = "Tue/Thu 1:00–2:30 PM", DepartmentId = 2, Instructor = _instructors[1], Department = _departments[1] },
            new() { Id = 6, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes laboratory component.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM + Lab Thu 2:00–4:00 PM", DepartmentId = 3, Instructor = _instructors[2], Department = _departments[2], IsFeatured = true },
            new() { Id = 7, Code = "PHYS 340", Title = "Quantum Mechanics", Description = "Wave-particle duality, Schrödinger equation, quantum states, and measurement theory.", Credits = 3, Schedule = "Tue/Thu 9:00–10:30 AM", DepartmentId = 3, Instructor = _instructors[2], Department = _departments[2] },
            new() { Id = 8, Code = "ENG 110", Title = "College Writing", Description = "Development of analytical writing skills through reading and composition. Emphasis on argumentation and evidence.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", DepartmentId = 4, Instructor = _instructors[3], Department = _departments[3] },
            new() { Id = 9, Code = "ENG 350", Title = "American Literature", Description = "Survey of American literary traditions from the colonial period to the present.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:30 PM", DepartmentId = 4, Instructor = _instructors[3], Department = _departments[3] },
            new() { Id = 10, Code = "HIST 101", Title = "World Civilizations", Description = "Survey of major world civilizations from antiquity to the early modern period.", Credits = 3, Schedule = "Mon/Wed/Fri 2:00–2:50 PM", DepartmentId = 5, Instructor = _instructors[4], Department = _departments[4] },
            new() { Id = 11, Code = "HIST 320", Title = "Medieval Europe", Description = "Political, social, and cultural history of Europe from the fall of Rome to the Renaissance.", Credits = 3, Schedule = "Tue/Thu 3:00–4:30 PM", DepartmentId = 5, Instructor = _instructors[4], Department = _departments[4] },
            new() { Id = 12, Code = "CS 201", Title = "Object-Oriented Programming", Description = "Design principles, inheritance, polymorphism, and design patterns using C# and Java.", Credits = 3, Schedule = "Tue/Thu 9:00–10:30 AM", DepartmentId = 1, Instructor = _instructors[5], Department = _departments[0] }
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses() => _courses;

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public List<Course> SearchCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Instructor.Name.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetCoursesByDepartment(int departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).ToList();

    public void SubmitEnrollment(EnrollmentRequest request)
    {
        _enrollments.Add(request);
    }
}

